pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        vm.assume(amount1 > 0);
        vm.assume(amount2 > 0);
        vm.assume(amount2 <= amount1);
        address receiver = address(this);
        bool reverted1;
        try c.sendTo(receiver, amount1) { reverted1 = false; } catch { reverted1 = true; }
        bool reverted2;
        try c.sendTo(receiver, amount2) { reverted2 = false; } catch { reverted2 = true; }
        assertTrue(!reverted1 || reverted2);
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
